package com.example.kousaku.controller;
import com.example.kousaku.model.Inquiry; import com.example.kousaku.service.InquiryService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/staff/inquiries") public class StaffInquiryController { private final InquiryService service; public StaffInquiryController(InquiryService s){service=s;} @GetMapping public List<Inquiry> list(){return service.findAll();} @GetMapping("/{id}") public Inquiry detail(@PathVariable Long id){return required(service.findById(id));} @PatchMapping("/{id}/status") public Inquiry status(@PathVariable Long id,@RequestBody StatusRequest r){try{return required(service.updateStatus(id,r.status()));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}} @PatchMapping("/{id}/reply") public Inquiry reply(@PathVariable Long id,@RequestBody ReplyRequest r){try{return required(service.reply(id,r.replyMessage()));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}} private Inquiry required(Inquiry i){if(i==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return i;} public record StatusRequest(String status){} public record ReplyRequest(String replyMessage){} }
